<script setup lang="ts">
import OptionSelect from '@/Components/UI/OptionSelect.vue';
import { MDT_NOTE_CATEGORIES } from '@/utils/caseOptions';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head } from '@inertiajs/vue3';
import { computed, onMounted, ref } from 'vue';

type MdtNote = { id: number; category: string; status: string; previous_note_id?: number | null; addendum_reason?: string | null };
type MdtAction = { id: number; title: string; status: string; due_at?: string | null };
const props = defineProps<{ caseId: number }>();
const data = ref<any>(null); const thread = ref<any[]>([]); const status = ref('Loading authorized collaboration…');
const message = ref(''); const file = ref<File | null>(null); const purpose = ref('supporting_record');
const relatedAction = ref(''); const relatedNote = ref(''); const noteCategory = ref(''); const noteFindings = ref(''); const noteRecommendation = ref('');
const addendumFor = ref<MdtNote | null>(null); const addendumReason = ref('');
const unread = computed(() => data.value?.unread_discussions ?? 0);
async function load() { try { const [caseData, discussion] = await Promise.all([window.axios.get(route('cases.mdt.show', props.caseId)), window.axios.get(route('cases.mdt.discussion.index', props.caseId))]); data.value = caseData.data; thread.value = discussion.data; status.value = 'Ready'; } catch { status.value = 'Access unavailable or ended. Check your active MDT assignment.'; } }
async function post() { status.value = 'Posting message…'; try { await window.axios.post(route('cases.mdt.discussion.store', props.caseId), { body: message.value }); message.value = ''; await load(); } catch { status.value = 'Message failed - retry when connected.'; } }
async function respond(item: MdtAction, response: 'responded' | 'completed') { status.value = 'Saving action response…'; try { await window.axios.patch(route('cases.mdt.actions.respond', [props.caseId, item.id]), { status: response }); await load(); } catch { status.value = 'Action update failed - retry when connected.'; } }
async function saveNote() { status.value = 'Saving MDT note…'; try { await window.axios.post(route('cases.mdt.notes.store', props.caseId), { category: noteCategory.value, findings: noteFindings.value || null, recommendation: noteRecommendation.value || null }); noteCategory.value = ''; noteFindings.value = ''; noteRecommendation.value = ''; await load(); } catch { status.value = 'Note save failed - retry when connected.'; } }
async function finalize(item: MdtNote) { status.value = 'Finalizing note…'; try { await window.axios.patch(route('cases.mdt.notes.finalize', [props.caseId, item.id])); await load(); } catch { status.value = 'Finalization failed - retry when connected.'; } }
async function addendum() { if (!addendumFor.value) return; status.value = 'Saving immutable addendum…'; try { await window.axios.post(route('cases.mdt.notes.addendum', [props.caseId, addendumFor.value.id]), { reason: addendumReason.value, category: noteCategory.value, findings: noteFindings.value || null, recommendation: noteRecommendation.value || null }); addendumFor.value = null; addendumReason.value = ''; noteCategory.value = ''; noteFindings.value = ''; noteRecommendation.value = ''; await load(); } catch { status.value = 'Addendum failed - retry when connected.'; } }
async function upload() { if (!file.value) return; status.value = 'Uploading authorized file…'; try { const form = new FormData(); form.append('attachment', file.value); form.append('purpose_category', purpose.value); if (relatedAction.value) form.append('mdt_action_id', relatedAction.value); if (relatedNote.value) form.append('mdt_note_id', relatedNote.value); await window.axios.post(route('cases.mdt.attachments.store', props.caseId), form); file.value = null; relatedAction.value = ''; relatedNote.value = ''; await load(); } catch { status.value = 'Upload failed - retry when connected.'; } }
onMounted(load);
</script>

<template>
  <Head title="MDT case collaboration" />
  <AuthenticatedLayout>
    <main class="mx-auto max-w-4xl px-4 py-6 sm:px-6">
      <header class="ui-panel p-5 sm:p-7">
        <p class="text-sm font-bold text-brand-700">Case-specific collaboration</p>
        <h1 class="mt-1 text-2xl font-extrabold text-slate-900 sm:text-3xl">{{ data?.case_number || 'Loading' }}</h1>
        <p class="mt-2 max-w-3xl text-sm leading-6 text-slate-600">Only information and files explicitly authorized for this active grant are available.</p>
      </header>
      <p class="mt-3 text-sm" aria-live="polite">{{ status }}</p>
      <section v-if="data" class="mt-5 grid gap-4 sm:grid-cols-2"><article class="rounded-2xl border bg-white p-5"><h2 class="font-bold">Grant status</h2><p class="mt-2 text-sm">{{ data.status }}</p><p class="text-sm">Expires: {{ data.grant.access_expires_at }}</p></article><article class="rounded-2xl border bg-white p-5"><h2 class="font-bold">Discussion</h2><p class="mt-2 text-sm"><span class="font-semibold">{{ unread }}</span> unread before opening this workspace.</p><p class="text-sm text-slate-600">Viewing the thread records your last-read time.</p></article></section>
      <section v-if="data" class="mt-5 rounded-2xl border bg-white p-5"><h2 class="font-bold">Assigned actions</h2><article v-for="item in data.actions as MdtAction[]" :key="item.id" class="mt-3 rounded-xl bg-slate-50 p-3 text-sm"><b>{{ item.title }}</b><p class="mt-1">Status: {{ item.status }}<span v-if="item.due_at"> · Due {{ item.due_at }}</span></p><div v-if="!['responded', 'completed'].includes(item.status)" class="mt-2 flex flex-wrap gap-2"><button type="button" class="rounded-lg border px-3 py-2 font-bold" @click="respond(item, 'responded')">Mark responded</button><button type="button" class="rounded-lg bg-brand-700 px-3 py-2 font-bold text-white" @click="respond(item, 'completed')">Mark complete</button></div></article><p v-if="!data.actions.length" class="mt-2 text-sm text-slate-500">No action assigned.</p></section>
      <section class="mt-5 rounded-2xl border bg-white p-5" aria-label="MDT discussion"><h2 class="font-bold">MDT Discussion</h2><article v-for="item in thread" :key="item.id" class="mt-3 rounded-xl bg-slate-50 p-3 text-sm"><b>{{ item.author }}</b> <span class="text-xs text-slate-500">{{ item.author_role }} · {{ item.created_at }}</span><p class="mt-1 whitespace-pre-wrap">{{ item.body }}</p></article><form class="mt-4" @submit.prevent="post"><label for="message" class="text-sm font-bold">Coordination message</label><textarea id="message" v-model="message" required rows="4" class="mt-2 w-full rounded-xl border-slate-300" /><button class="mt-2 rounded-xl bg-brand-700 px-3 py-2 text-sm font-bold text-white">Post message</button></form></section>
      <section v-if="data" class="mt-5 rounded-2xl border bg-white p-5"><h2 class="font-bold">MDT case notes</h2><p class="mt-1 text-sm text-slate-600">Final notes are immutable. Use a linked addendum to correct or supplement one.</p><article v-for="item in data.notes as MdtNote[]" :key="item.id" class="mt-3 rounded-xl bg-slate-50 p-3 text-sm"><b>{{ item.category }}</b><span class="ml-2 rounded-full bg-slate-200 px-2 py-1 text-xs font-bold">{{ item.status }}</span><p v-if="item.previous_note_id" class="mt-1 text-xs text-slate-600">Addendum to note #{{ item.previous_note_id }} · Reason: {{ item.addendum_reason }}</p><div class="mt-2 flex flex-wrap gap-2"><button v-if="item.status === 'draft'" type="button" class="rounded-lg bg-brand-700 px-3 py-2 font-bold text-white" @click="finalize(item)">Finalize note</button><button v-if="item.status === 'final'" type="button" class="rounded-lg border px-3 py-2 font-bold" @click="addendumFor = item">Add addendum</button></div></article><form class="mt-4 grid gap-3" @submit.prevent="addendumFor ? addendum() : saveNote()"><p class="font-bold">{{ addendumFor ? `Addendum to note #${addendumFor.id}` : 'New MDT note' }}</p><label v-if="addendumFor" class="text-sm font-bold">Reason for addendum<textarea v-model="addendumReason" required rows="2" class="mt-1 w-full rounded-xl border-slate-300" /></label><label class="text-sm font-bold">Category<OptionSelect v-model="noteCategory" :options="MDT_NOTE_CATEGORIES" required /></label><label class="text-sm font-bold">Findings<textarea v-model="noteFindings" rows="3" class="mt-1 w-full rounded-xl border-slate-300" /></label><label class="text-sm font-bold">Recommendation<textarea v-model="noteRecommendation" rows="3" class="mt-1 w-full rounded-xl border-slate-300" /></label><div class="flex flex-wrap gap-2"><button class="rounded-xl bg-brand-700 px-3 py-2 text-sm font-bold text-white">{{ addendumFor ? 'Save final addendum' : 'Save draft note' }}</button><button v-if="addendumFor" type="button" class="rounded-xl border px-3 py-2 text-sm font-bold" @click="addendumFor = null">Cancel addendum</button></div></form></section>
      <section v-if="data" class="mt-5 rounded-2xl border bg-white p-5"><h2 class="font-bold">Authorized MDT attachments</h2><p class="mt-1 text-sm text-slate-500">This is grant-scoped and separate from the general case document repository.</p><form class="mt-3 grid gap-3 sm:grid-cols-2" @submit.prevent="upload"><label class="text-sm font-bold">File<input required type="file" accept="application/pdf,image/jpeg,image/png,.doc,.docx" class="mt-1 block w-full" @change="file = ($event.target as HTMLInputElement).files?.[0] || null" /></label><label class="text-sm font-bold">Purpose<select v-model="purpose" class="mt-1 w-full rounded-xl border-slate-300"><option value="supporting_record">Supporting record</option><option value="service_response">Service response</option><option value="professional_observation">Professional observation</option></select></label><label class="text-sm font-bold">Related action<select v-model="relatedAction" class="mt-1 w-full rounded-xl border-slate-300"><option value="">None</option><option v-for="item in data.actions" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label class="text-sm font-bold">Related note<select v-model="relatedNote" class="mt-1 w-full rounded-xl border-slate-300"><option value="">None</option><option v-for="item in data.notes" :key="item.id" :value="item.id">{{ item.category }} #{{ item.id }}</option></select></label><button class="w-fit rounded-xl bg-brand-700 px-3 py-2 text-sm font-bold text-white">Upload authorized file</button></form><article v-for="item in data.attachments" :key="item.id" class="mt-3 flex flex-wrap justify-between gap-2 rounded-xl bg-slate-50 p-3 text-sm"><div><b>{{ item.name }}</b><p class="text-xs text-slate-500">{{ item.purpose_category }} · {{ item.mime_type }} · {{ Math.ceil(item.size_bytes / 1024) }} KB</p></div><a :href="route('cases.mdt.attachments.download', [caseId, item.id])" class="rounded-lg border px-3 py-2 text-xs font-bold">Download authorized file</a></article><p v-if="!data.attachments.length" class="mt-3 text-sm text-slate-500">No attachment shared under this grant.</p></section>
    </main>
  </AuthenticatedLayout>
</template>
